export function translateSection(section: AdminSectionConfig, lang: string): AdminSectionConfig {
  const key = section.key
  const langPack = SECTION_I18N[lang] || SECTION_I18N.en
  const tr = langPack[key]
  if (!tr) return section
  const nt = NOT_TRACKED[lang] || NOT_TRACKED.en
  return {
    ...section,
    title: tr.title,
    description: tr.description,
    tableTitle: tr.tableTitle,
    tableColumns: tr.tableColumns,
    cockpit: tr.cockpit ?? section.cockpit,
    metrics: section.metrics.map((m, i) => ({ ...m, label: tr.metrics[i] ?? m.label, value: m.value === 'Not tracked yet' ? nt : m.value })),
  }
}
